import{_ as o,l as r,o as e,c as d,v as n,p as s,x as t,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"栈展开与 unwind 表","description":"","frontmatter":{"title":"栈展开与 unwind 表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stack-unwinding.md","filePath":"cs/stack-unwinding.md","lastUpdated":1789023840000}'),u={name:"cs/stack-unwinding.md"};function h(_,a,m,A,f,F){const i=r("Mermaid");return e(),d("div",null,[a[1]||(a[1]=n('<h1 id="栈展开与-unwind-表" tabindex="-1">栈展开与 unwind 表 <a class="header-anchor" href="#栈展开与-unwind-表" aria-label="Permalink to &quot;栈展开与 unwind 表&quot;">​</a></h1><div class="epigraph"><p>异常、调试器、profiler 要沿帧走回调用者。省略帧指针后，靠 DWARF CFI 或 `.eh_frame` 描述如何恢复寄存器与 CFA。</p><footer>—— 据 DWARF Debugging Information Format；Itanium C++ ABI 异常；主干[异常表](/cs/exception-table) 整理</footer></div><p>上一课<a href="/cs/stack-frame-layout">栈帧布局</a>可 omit FP。缺口是<strong>运行时如何展开</strong>：表驱动恢复。C++ <code>throw</code>、Rust panic、<code>backtrace</code> 都读 unwind 表。本课钉 CFI 与 LSDA，不写完整语言异常语义。调试信息下一课更广（类型、行号）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有 FP：链简单。无 FP：必须知道每条指令处 SP 相对 CFA、callee-save 存在哪。CFI：状态机，<code>advance_loc</code>、<code>offset</code>。缺口是<strong>编译器发表</strong>，不是 catch 语法。</p><p>异常：personality 例程 + LSDA 决定这一帧是否处理。与<a href="/cs/tail-call-opt">尾调用</a>：被优化掉的帧在表上消失。</p><h3 id="unwind-不是「反汇编猜-push」" tabindex="-1">unwind 不是「反汇编猜 push」 <a class="header-anchor" href="#unwind-不是「反汇编猜-push」" aria-label="Permalink to &quot;unwind 不是「反汇编猜 push」&quot;">​</a></h3><p>启发式 backtrace 在优化代码上失败。可靠路径是表。JIT 必须运行时注册表。</p><p><span class="marginnote">DWARF 标准。Itanium C++ ABI。libunwind。主干 exception-table 课已有直觉，本课接后端发射。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对序言/收尾每步发 CFI。压缩成 CIE/FDE。链接器合并 <code>.eh_frame</code>。可选 <code>.eh_frame_hdr</code> 加速查找。</p>',11)),(e(),s(p,null,{default:t(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PC%5B%22%E5%BD%93%E5%89%8D%20PC%22%5D%20--%3E%20FDE%5B%22%E6%9F%A5%20FDE%22%5D%0A%20%20FDE%20--%3E%20CFA%5B%22%E6%81%A2%E5%A4%8D%20CFA%20%E4%B8%8E%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20CFA%20--%3E%20PREV%5B%22%E4%B8%8A%E4%B8%80%E5%B8%A7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>与分配：spill 位置必须与 CFI 一致，否则展开读垃圾。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>异步 unwind（信号中）要求每条指令都正确，代价高；同步（throw 点）可只在可能抛的点精确。不要在省略表（<code>-fno-exceptions</code>）的 C 里假设能 catch。</p><p>安全：伪造表可跳到任意 personality——加载信任。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 DWARF 表达式。后课默认：无 FP 靠 unwind 表。下一课 DWARF 调试信息（行号、类型）。</p><p>也不把 unwind 当栈溢出利用教程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>展开：CFI/FDE 描述如何从 PC 恢复上一帧。</li><li>异常用同一基础设施加 LSDA。</li><li>与帧布局、分配必须一致。</li><li>出处：DWARF；Itanium C++ ABI；对照龙书异常。</li></ul>',9))])}const E=o(u,[["render",h]]);export{C as __pageData,E as default};
